INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp1','am3_l07','名词→形容词 -ful/-less(care→careful/careless)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp2','am3_l07','名词→形容词 -ish/-ic(fool→foolish/energetic)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp3','am3_l07','名词→形容词 -ous/-y(danger→dangerous/lucky)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp4','am3_l07','一般过去时叙事(承载官方KS)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp5','am3_l07','现在完成的经历疑问(Have you ever...?)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l07_gp6','am3_l07','词汇辨析(chew/identify/spokeswoman)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l07','pants','trousers','裤子;美语 pants,英式 trousers') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l07','bill','note','钞票;美语 bill,英式 (bank)note') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l07','cookie','biscuit','饼干;美语 cookie,英式 biscuit') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l07','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l07','for safekeeping','',NULL,'/fɔːr ˈseɪfkiːpɪŋ/','He hid the cash in the oven for safekeeping.','他把现金藏在烤箱里以为妥善保管。','She left her ring with me for safekeeping.','她把戒指交给我保管。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l07','chew up','',NULL,'/tʃuː ʌp/','The dog chewed up the money.','狗把钱嚼烂了。','The puppy chewed up my shoe.','小狗把我的鞋咬烂了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l07','as long as','',NULL,'/æz lɔːŋ æz/','As long as it can be identified, they return the money.','只要还能辨认,他们就退钱。','You can stay as long as you keep quiet.','只要你保持安静,就可以待着。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l07','without realizing it','',NULL,'/wɪˈðaʊt ˈriːəlaɪzɪŋ ɪt/','She turned on the microwave without realizing it.','她没意识到就开了微波炉。','He deleted the file without realizing it.','他没察觉就把文件删了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp1','choice','{"stem":"\"Carlos runs a very ___ bakery; it makes good money.\"(“成功的”,用哪个形容词)","options":["successless","succeedic","successful","success"],"answer_index":2,"stem_cn":"Carlos 经营着一家很成功的面包店,很赚钱。","explanation_cn":"名词 success 加后缀 -ful 变形容词 successful(成功的)。✓ a successful bakery. ✗ success 是名词;✗ successless / succeedic 都不是真实的词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp1','choice','{"stem":"\"The burned money was now just a pile of ___ ash.\"(“无用的”,用哪个形容词)","options":["useish","useless","usely","useful"],"answer_index":1,"stem_cn":"烧掉的钱如今只是一堆没用的灰。","explanation_cn":"名词 use 加后缀 -less 表示“没有……的、无用的”:useless。✓ a pile of useless ash. ✗ useful 是“有用的”意思相反;✗ usely / useish 不是词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp1','choice','{"stem":"\"Be ___ with cash near a hot stove — accidents happen fast.\"(“小心的”,用哪个形容词)","options":["carely","careless","careic","careful"],"answer_index":3,"stem_cn":"在热炉旁放现金要小心——出事就在一瞬间。","explanation_cn":"名词 care 加 -ful 变 careful(小心的);加 -less 则是 careless(粗心的),意思相反。这里劝人“要小心”,用 careful。✓ Be careful with cash. ✗ careless 是“粗心的”相反;✗ carely / careic 不是词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp2','choice','{"stem":"\"Hiding money in the microwave was a rather ___ idea.\"(“愚蠢的”,用哪个形容词)","options":["foolless","foolic","foolish","foolful"],"answer_index":2,"stem_cn":"把钱藏微波炉里是个相当愚蠢的主意。","explanation_cn":"名词 fool 加后缀 -ish 变 foolish(愚蠢的)。✓ a foolish idea. ✗ foolful / foolic / foolless 都不是真实的词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp2','choice','{"stem":"\"The young bakers are ___, always full of energy.\"(“精力充沛的”,用哪个形容词)","options":["energish","energetic","energyful","energyless"],"answer_index":1,"stem_cn":"那些年轻面包师精力充沛,总是活力满满。","explanation_cn":"名词 energy 变形容词要改拼写、加 -ic:energetic(精力充沛的)。✓ young and energetic. ✗ energyful / energish / energyless 都不是词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp2','choice','{"stem":"\"Stop pouting — you''re being ___ again like a little kid.\"(“孩子气的、幼稚的”,用哪个形容词)","options":["childish","childic","childful","childless"],"answer_index":0,"stem_cn":"别撅嘴了——你又像个小孩似的耍幼稚。","explanation_cn":"名词 child 加 -ish 变 childish(孩子气的、幼稚的)。✓ you''re being childish. ✗ childful / childic / childless(childless 另指“没有孩子的”,这里不合)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp3','choice','{"stem":"\"Leaving money in a hot oven is ___.\"(“危险的”,用哪个形容词)","options":["dangerish","dangerous","dangerful","dangery"],"answer_index":1,"stem_cn":"把钱留在热烤箱里很危险。","explanation_cn":"名词 danger 加后缀 -ous 变 dangerous(危险的)。✓ it is dangerous. ✗ dangerful / dangery / dangerish 都不是词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp3','choice','{"stem":"\"After the bakery grew, Carlos became quite ___ in town.\"(“出名的”,用哪个形容词)","options":["fameful","famish","famous","famely"],"answer_index":2,"stem_cn":"面包店做大后,Carlos 在镇上相当有名。","explanation_cn":"名词 fame 变形容词要改拼写、加 -ous:famous(出名的)。✓ he became famous. ✗ fameful / famish / famely 都不是词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp3','choice','{"stem":"\"They were very ___ to get all their money back.\"(“幸运的”,用哪个形容词)","options":["lucky","luckous","luckish","luckful"],"answer_index":0,"stem_cn":"能把钱如数要回来,他们很幸运。","explanation_cn":"名词 luck 加 -y 变 lucky(幸运的)。✓ they were very lucky. ✗ luckful / luckous / luckish 都不是词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp4','choice','{"stem":"\"Maria ___ on the microwave without realizing the money was inside.\"(讲过去发生:一般过去时)","options":["turns","has turned","was turning","turned"],"answer_index":3,"stem_cn":"玛丽亚没意识到钱在里面就开了微波炉。","explanation_cn":"“开微波炉”是过去发生、已完成的动作,用一般过去时。✓ Maria turned on the microwave. ✗ was turning:这里不是强调“正在开”;✗ turns / has turned:时态不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp4','choice','{"stem":"\"Carlos ___ the burned remains to the special office.\"(讲过去发生:一般过去时)","options":["mailed","has mailed","mails","was mailing"],"answer_index":0,"stem_cn":"Carlos 把烧焦的残余寄给了那个专门部门。","explanation_cn":"“把残余寄出去”是过去发生的动作,用一般过去时。✓ Carlos mailed the remains. ✗ was mailing / mails / has mailed:时态不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp4','choice','{"stem":"\"A few weeks later, he ___ all of his money back.\"(讲过去发生:get 的过去式)","options":["was getting","gets","got","has got"],"answer_index":2,"stem_cn":"几周后,他把所有的钱都要了回来。","explanation_cn":"get 的过去式是不规则的 got;“几周后把钱拿了回来”讲过去。✓ he got his money back. ✗ was getting / gets / has got:时态不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp5','choice','{"stem":"\"___ it ever happened to you? Money washed by mistake?\"(问“有没有发生过”:现在完成的疑问)","options":["Has","Was","Is","Did"],"answer_index":0,"stem_cn":"这种事发生过在你身上吗?钱被误洗了?","explanation_cn":"“这种事发生过吗”问的是到现在为止的经历,用现在完成的疑问 Has it happened…。✓ Has it ever happened to you? ✗ Did:那是一般过去的疑问;✗ Was / Is:配不出现在完成。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp5','choice','{"stem":"\"Have you ever ___ money in the wash by accident?\"(现在完成的经历:选过去分词)","options":["ruins","ruin","ruined","ruining"],"answer_index":2,"stem_cn":"你有没有不小心把钱洗坏过?","explanation_cn":"“有没有……过”是现在完成的经历,have 后面用过去分词;ruin 的过去分词是 ruined。✓ Have you ever ruined money…? ✗ ruin / ruins / ruining:都不是过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp6','choice','{"stem":"\"Dogs seem to love to ___ up money and paper.\"(“咀嚼、咬”,用哪个词)","options":["paint","chew","plant","wash"],"answer_index":1,"stem_cn":"狗似乎特别爱把钱和纸嚼烂。","explanation_cn":"“咀嚼、咬(烂)”用 chew。✓ dogs love to chew up money. ✗ wash 洗;✗ paint 涂;✗ plant 种——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp6','choice','{"stem":"\"The bank returns damaged money only if experts can ___ it.\"(“鉴定、辨认”,用哪个词)","options":["identify","spend","destroy","borrow"],"answer_index":0,"stem_cn":"只有专家能辨认出来,银行才退还残币。","explanation_cn":"“鉴定、辨认出”用 identify。✓ if experts can identify it. ✗ destroy 毁坏;✗ borrow 借入;✗ spend 花掉——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp6','choice','{"stem":"\"A woman who speaks for a company or a bank is a ___.\"(“女发言人”,用哪个词)","options":["neighbor","stranger","spokeswoman","customer"],"answer_index":2,"stem_cn":"代表公司或银行讲话的女性是女发言人。","explanation_cn":"代表公司或银行讲话的女性叫 spokeswoman(女发言人)。✓ a spokeswoman explained. ✗ customer 顾客;✗ neighbor 邻居;✗ stranger 陌生人——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',5,'am3_l07_gp6','choice','{"stem":"\"Carlos put the cash in the microwave for ___.\"(“妥善保管”,用哪个词)","options":["cooking","safekeeping","selling","cleaning"],"answer_index":1,"stem_cn":"Carlos 把现金放进微波炉是为了妥善保管。","explanation_cn":"“为妥善保管”用 for safekeeping。✓ put the cash there for safekeeping. ✗ cooking 做饭;✗ cleaning 打扫;✗ selling 出售——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"美语里\"裤子\"常说:","options":["leg-wear","trousers","pants","cloth-legs"],"answer_index":2,"explanation_cn":"美语里“裤子”常说 pants(英式说 trousers)。✓ money in your pants pocket."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"chew 的意思是:","options":["咀嚼,咬","洗涤","折叠","撕开"],"answer_index":0,"explanation_cn":"chew = 咀嚼、咬(烂)。✓ chew up money 把钱嚼烂。\n顺带记:洗涤 = wash;折叠 = fold;撕开 = tear."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"identify 的意思是:","options":["出售","鉴定,辨认","损坏","隐藏"],"answer_index":1,"explanation_cn":"identify = 鉴定、辨认出。✓ enough left to identify 还剩够辨认的。\n顺带记:隐藏 = hide;出售 = sell;损坏 = damage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"spokeswoman 的意思是:","options":["女发言人","陌生人","顾客","邻居"],"answer_index":0,"explanation_cn":"spokeswoman = 女发言人(代表机构讲话的女性)。✓ a spokeswoman explained 一位女发言人解释道。\n顺带记:顾客 = customer;邻居 = neighbor;陌生人 = stranger."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"\"safekeeping\" 的意思是:","options":["大扫除","搬家","妥善保管","打折"],"answer_index":2,"explanation_cn":"safekeeping = 妥善保管。✓ for safekeeping 为了妥善保管。\n顺带记:大扫除 = big clean-up;打折 = discount;搬家 = move house."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',6,NULL,'choice','{"stem":"successful 的意思是:","options":["免费的","成功的","危险的","失败的"],"answer_index":1,"explanation_cn":"successful = 成功的(名词 success 加 -ful)。✓ a successful bakery 一家成功的面包店。\n顺带记:失败的 = failed;免费的 = free;危险的 = dangerous."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',7,NULL,'cloze','{"stem":"第 1 空","context":"Carlos runs a very ___1___ bakery. One day he hid three thousand dollars in the microwave for safekeeping. Later his fiancée ___2___ on the microwave by mistake and burned it all. What a ___3___ place to hide money! Luckily, experts could still ___4___ the ash, so the bank returned every dollar.","blank_no":1,"options":["successful","success","successless","succeed"],"answer_index":0,"explanation_cn":"名词 success 加 -ful 变形容词 successful(成功的)。✓ a very successful bakery."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',7,NULL,'cloze','{"stem":"第 2 空","context":"Carlos runs a very ___1___ bakery. One day he hid three thousand dollars in the microwave for safekeeping. Later his fiancée ___2___ on the microwave by mistake and burned it all. What a ___3___ place to hide money! Luckily, experts could still ___4___ the ash, so the bank returned every dollar.","blank_no":2,"options":["turns","turned","was turning","has turned"],"answer_index":1,"explanation_cn":"“误开微波炉”是过去发生的动作,用一般过去时。✓ his fiancée turned on the microwave."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',7,NULL,'cloze','{"stem":"第 3 空","context":"Carlos runs a very ___1___ bakery. One day he hid three thousand dollars in the microwave for safekeeping. Later his fiancée ___2___ on the microwave by mistake and burned it all. What a ___3___ place to hide money! Luckily, experts could still ___4___ the ash, so the bank returned every dollar.","blank_no":3,"options":["foolish","fool","foolness","foolist"],"answer_index":0,"explanation_cn":"名词 fool 加 -ish 变 foolish(愚蠢的);“藏钱的地方真愚蠢”。✓ What a foolish place to hide money!"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',7,NULL,'cloze','{"stem":"第 4 空","context":"Carlos runs a very ___1___ bakery. One day he hid three thousand dollars in the microwave for safekeeping. Later his fiancée ___2___ on the microwave by mistake and burned it all. What a ___3___ place to hide money! Luckily, experts could still ___4___ the ash, so the bank returned every dollar.","blank_no":4,"options":["ignore","identify","destroy","borrow"],"answer_index":1,"explanation_cn":"“辨认出”用 identify;只要专家能辨认残币,银行就退钱。✓ experts could still identify the ash."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',8,NULL,'choice','{"stem":"Where did Carlos hide his money?","options":["In his dog''s bed","In a bank vault","In the microwave oven","Under his bed"],"answer_index":2,"explanation_cn":"课文说 Carlos… tucked three thousand dollars into the microwave oven——他把钱藏在了微波炉里。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',8,NULL,'choice','{"stem":"What happened to the money?","options":["It was burned to ash","It was washed away","It was stolen","A dog ate it"],"answer_index":0,"explanation_cn":"课文说 they found a neat stack of useless ash where the money had been——钱被烧成了灰。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',8,NULL,'choice','{"stem":"Why did Carlos get his money back?","options":["He knew the bank manager","Enough was left to identify it","He had insurance","He complained loudly"],"answer_index":1,"explanation_cn":"课文说 As long as there is enough left to identify, we return people''s money——因为还剩下够辨认的部分,所以退钱。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',9,NULL,'choice','{"stem":"你想说\"你有没有不小心把钱和衣服一起洗过?\"(现在完成的经历疑问):","options":["Have you ever wash money with your clothes by mistake?","Have you ever washed money with your clothes by mistake?","Did you ever have washed money with your clothes?","Are you ever washing money with your clothes?"],"answer_index":1,"explanation_cn":"问“有没有……过”这类经历,用现在完成的疑问 Have you ever + 过去分词。✓ Have you ever washed money with your clothes by mistake? 场合:问对方过去有没有这种经历。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',9,NULL,'choice','{"stem":"你想说\"他经营着一家成功的面包店\"(名词 success 变形容词 successful):","options":["He runs a succeed bakery.","He runs a success bakery.","He runs a successfully bakery.","He runs a successful bakery."],"answer_index":3,"explanation_cn":"名词 success 要变成形容词 successful 才能修饰 bakery。✓ He runs a successful bakery. 场合:用形容词描述“成功的”店/人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',9,NULL,'choice','{"stem":"你想说\"只要还能辨认,银行就退钱\"(as long as + identify):","options":["As long as they identifying it, the bank returns the money.","As long as they can identifies it, the bank return the money.","As long as they can identify it, the bank returns the money.","So long they can identify it, the bank returns money."],"answer_index":2,"explanation_cn":"as long as = 只要;意思是“只要他们能辨认出来,银行就退钱”。can 后面用原形 identify,the bank 是第三人称单数所以 returns 加 s。✓ As long as they can identify it, the bank returns the money. 场合:表示“只要满足某条件,就……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"identify 的意思是:","options":["隐藏","出售","损坏","鉴定,辨认"],"answer_index":3,"explanation_cn":"identify = 鉴定、辨认出。✓ enough left to identify."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"chew 的意思是:","options":["洗涤","折叠","咀嚼,咬","撕开"],"answer_index":2,"explanation_cn":"chew = 咀嚼、咬。✓ chew up money 把钱嚼烂。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"\"Maria ___ on the microwave without realizing the money was inside.\"(讲过去发生:一般过去)","options":["turns","turned","was turning","has turned"],"answer_index":1,"stem_cn":"玛丽亚没意识到钱在里面就开了微波炉。","explanation_cn":"“误开微波炉”是过去发生的动作,用一般过去时。✓ Maria turned on the microwave. ✗ was turning / turns / has turned:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"\"He runs a very ___ bakery.\"(名词 success 变形容词)","options":["succeed","successless","successful","success"],"answer_index":2,"stem_cn":"他经营着一家非常成功的面包店。","explanation_cn":"名词 success 加 -ful 变形容词 successful(成功的)。✓ a very successful bakery. ✗ success 是名词;✗ successless / succeed 不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"\"for safekeeping\" 的意思是:","options":["为了展示","为了妥善保管","为了出售","为了清洗"],"answer_index":1,"explanation_cn":"for safekeeping = 为了妥善保管。✓ He put it there for safekeeping."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"\"chew up\" 的意思是:","options":["叠整齐","擦干净","包起来","咬碎,嚼烂"],"answer_index":3,"explanation_cn":"chew up = 咬碎、嚼烂。✓ The dog chewed up the money 狗把钱嚼烂了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"What does the Mutilated Currency Division do?","options":["It trains guard dogs","It reimburses people for badly damaged money","It prints brand-new money","It fixes broken ovens"],"answer_index":1,"passage":"Has it ever happened to you? Have you ever left a twenty-dollar bill in your jeans and then tossed them into the washing machine? When you rescued your jeans, did you find the bill washed to a pale, soggy mess? Americans who make mistakes like this — and plenty do — need not despair. The U.S. Bureau of Engraving and Printing has a special office, the Mutilated Currency Division, that handles claims from people who have burned, soaked, or fed their money to a hungry dog. Dogs, it seems, love to chew up cash! One recent case involved a baker named Carlos and his fiancée, Maria, who together run a successful shop. Carlos had a very good day and, for safekeeping, tucked three thousand dollars into the microwave oven. Later, without realizing it, Maria turned on the microwave to heat some soup. Imagine their dismay when they opened the door and found a neat stack of useless ash where the money had been! Carlos mailed the burned remains to the Division. Careful experts examined every scrap, and a few weeks later he got all his money back. ''As long as there is enough left to identify, we return people''s money,'' a spokeswoman explained. ''Last year we paid out millions of dollars on thousands of claims.''","explanation_cn":"课文说残币鉴别组 handles claims from people who have burned, soaked, or fed their money to a dog——它给残损钱币的人赔付。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"How did the money get destroyed in this case?","options":["It was cooked in the microwave by mistake","It was left out in the rain","It was torn in half","A dog chewed it up"],"answer_index":0,"passage":"Has it ever happened to you? Have you ever left a twenty-dollar bill in your jeans and then tossed them into the washing machine? When you rescued your jeans, did you find the bill washed to a pale, soggy mess? Americans who make mistakes like this — and plenty do — need not despair. The U.S. Bureau of Engraving and Printing has a special office, the Mutilated Currency Division, that handles claims from people who have burned, soaked, or fed their money to a hungry dog. Dogs, it seems, love to chew up cash! One recent case involved a baker named Carlos and his fiancée, Maria, who together run a successful shop. Carlos had a very good day and, for safekeeping, tucked three thousand dollars into the microwave oven. Later, without realizing it, Maria turned on the microwave to heat some soup. Imagine their dismay when they opened the door and found a neat stack of useless ash where the money had been! Carlos mailed the burned remains to the Division. Careful experts examined every scrap, and a few weeks later he got all his money back. ''As long as there is enough left to identify, we return people''s money,'' a spokeswoman explained. ''Last year we paid out millions of dollars on thousands of claims.''","explanation_cn":"课文说 Maria turned on the microwave… found a neat stack of ash——这次钱是被误放进微波炉烧掉的。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"What did Carlos send to the special office?","options":["A brand-new wallet","A photo of the money","The burned remains of the money","A written complaint"],"answer_index":2,"audio":"Has it ever happened to you? Have you ever left a twenty-dollar bill in your jeans and then tossed them into the washing machine? When you rescued your jeans, did you find the bill washed to a pale, soggy mess? Americans who make mistakes like this — and plenty do — need not despair. The U.S. Bureau of Engraving and Printing has a special office, the Mutilated Currency Division, that handles claims from people who have burned, soaked, or fed their money to a hungry dog. Dogs, it seems, love to chew up cash! One recent case involved a baker named Carlos and his fiancée, Maria, who together run a successful shop. Carlos had a very good day and, for safekeeping, tucked three thousand dollars into the microwave oven. Later, without realizing it, Maria turned on the microwave to heat some soup. Imagine their dismay when they opened the door and found a neat stack of useless ash where the money had been! Carlos mailed the burned remains to the Division. Careful experts examined every scrap, and a few weeks later he got all his money back. ''As long as there is enough left to identify, we return people''s money,'' a spokeswoman explained. ''Last year we paid out millions of dollars on thousands of claims.''","explanation_cn":"课文说 Carlos mailed the burned remains to the Division——他寄去的是烧焦的钱币残余。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l07',10,NULL,'choice','{"stem":"How much did the office pay out last year?","options":["Nothing at all","Millions of dollars on thousands of claims","One single claim","Only ten dollars"],"answer_index":1,"audio":"Has it ever happened to you? Have you ever left a twenty-dollar bill in your jeans and then tossed them into the washing machine? When you rescued your jeans, did you find the bill washed to a pale, soggy mess? Americans who make mistakes like this — and plenty do — need not despair. The U.S. Bureau of Engraving and Printing has a special office, the Mutilated Currency Division, that handles claims from people who have burned, soaked, or fed their money to a hungry dog. Dogs, it seems, love to chew up cash! One recent case involved a baker named Carlos and his fiancée, Maria, who together run a successful shop. Carlos had a very good day and, for safekeeping, tucked three thousand dollars into the microwave oven. Later, without realizing it, Maria turned on the microwave to heat some soup. Imagine their dismay when they opened the door and found a neat stack of useless ash where the money had been! Carlos mailed the burned remains to the Division. Careful experts examined every scrap, and a few weeks later he got all his money back. ''As long as there is enough left to identify, we return people''s money,'' a spokeswoman explained. ''Last year we paid out millions of dollars on thousands of claims.''","explanation_cn":"课文说 Last year we paid out millions of dollars on thousands of claims——去年在成千上万宗索赔上赔了数百万美元。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l08',3,2,8,'The Mountain Monastery','山中修道院','被动语态各时态(一般现在被动 are sent/is visited、一般过去被动 was founded/were used、现在完成被动 has been built、情态/不定式被动 have to be kept/are allowed to),外加 -ever 复合词(whenever/wherever/whoever/whatever 加强语气)(原创承载 NCE3 L8 考点·落基山口老修道院与圣伯纳德救援犬)','落基山脉高处,鹰山口连着两条幽静的山谷。海拔一万一千多英尺,是全国最高的山口之一。近两百年前建起的一座石砌老修道院,就坐落在离顶不到一英里的地方。多少代以来,人们在那儿养着高大的圣伯纳德犬,专门营救被困雪中的旅人。这些温和的狗当初主要当看门狗养,如今只要有徒步者遇险,仍会被放出去闯进风雪。如今山中修了公路,山口安全多了。即便如此,还是有少数人冒冒失失地徒步翻越,而狗随时待命。夏天,修道院热闹非凡,成千上万开车上山的游客来参观。人一多,狗就得关进专门的围场。可一到冬天,一切都变了:气温降到零下很多,几乎没人来。修道士们更爱冬天,因为终于能清静些;狗也自由些,获准想去哪儿就去哪儿。冬天唯一的常客,是圣诞和复活节前来的一队队滑雪者。无论谁那时来访,总会受到热情的欢迎。','{"q":"Listen and answer — What are the St. Bernard dogs used for?","options":["Rescuing travelers caught in the snow","Guarding tourists'' cars","Pulling sleds of goods","Herding mountain sheep"],"answer_index":0}'::jsonb,'{"title":"被动语态各时态 + -ever 复合词","intro":"①被动语态=be + 过去分词,表示“被……”:一般现在被动 is/are + done(the dogs are sent out / it is visited)、一般过去被动 was/were + done(the monastery was founded / the dogs were used)、现在完成被动 has/have been + done(a highway has been built)、情态或不定式的被动(the dogs have to be kept / are allowed to wander)。be 用什么时态,就表达什么时候“被……”。②-ever 复合词:who/what/when/where/how 加 -ever,表示“无论谁/什么/何时/何地/怎样”,用来加强语气——whenever(无论何时)、wherever(无论何处)、whoever(无论谁)、whatever(无论什么)。","table":{"headers":["被动时态","结构","例子"],"rows":[["一般现在被动","is/are + 过去分词","The dogs are sent out. / It is visited by tourists."],["一般过去被动","was/were + 过去分词","The monastery was founded long ago."],["现在完成被动","has/have been + 过去分词","A highway has been built through the pass."],["-ever 复合词","who/what/when/where + ever","whenever / wherever / whoever / whatever"]]},"specialRules":[{"rule":"被动语态里,动作的承受者放在前面,be 决定时态:are kept(现在被关着)、were kept(过去被关着)、have been kept(到现在一直被关着)。情态词后用 be + 过去分词(must be kept / have to be kept)。","mark":"be + done"},{"rule":"-ever 复合词既能当连词引导让步(Whoever comes is welcome 无论谁来都欢迎),也能加强疑问语气(Wherever has he gone? 他到底去哪儿了)。","mark":"whenever/whoever"},{"rule":"美语里“假期”说 vacation(英式 holiday);“毛衣”说 sweater(英式 jumper)。本课已按美语写。","mark":"vacation / sweater"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l08',1,NULL,'High in the Rocky Mountains, Eagle Pass connects two quiet valleys. At over eleven thousand feet, it is one of the highest passes in the country. An old stone monastery, which was founded almost two hundred years ago, stands about a mile from the top.','落基山脉高处,鹰山口连着两条幽静的山谷。海拔一万一千多英尺,是全国最高的山口之一。近两百年前建起的一座石砌老修道院,就坐落在离顶不到一英里的地方。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l08',2,NULL,'For generations, big St. Bernard dogs have been kept there to rescue travelers caught in the snow. These gentle dogs, which were first raised as watchdogs, are still sent out into the storms whenever a hiker is in trouble.','多少代以来,人们在那儿养着高大的圣伯纳德犬,专门营救被困雪中的旅人。这些温和的狗当初主要当看门狗养,如今只要有徒步者遇险,仍会被放出去闯进风雪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l08',3,NULL,'A modern highway has now been built through the mountains, so the pass is much safer. Even so, a few people still rashly try to cross it on foot, and the dogs are always ready.','如今山中修了公路,山口安全多了。即便如此,还是有少数人冒冒失失地徒步翻越,而狗随时待命。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l08',4,NULL,'During the summer, the monastery is crowded, for it is visited by thousands of tourists who drive up to see it. Because so many people are around, the dogs have to be kept inside a special enclosure.','夏天,修道院热闹非凡,成千上万开车上山的游客来参观。人一多,狗就得关进专门的围场。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l08',5,NULL,'In winter, however, everything changes. The monks prefer winter to summer, because they finally have some privacy. The dogs are allowed to wander wherever they like. The only regular guests are groups of skiers who arrive at Christmas and Easter. Whoever visits then is always given a warm welcome.','可一到冬天,一切都变了。修道士们更爱冬天,因为终于能清静些;狗也获准想去哪儿就去哪儿。冬天唯一的常客,是圣诞和复活节前来的一队队滑雪者。无论谁那时来访,总会受到热情的欢迎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
