INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l08','sweater','jumper','毛衣;美语 sweater,英式 jumper') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l08','gas station','petrol station','加油站;美语 gas station,英式 petrol station') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l08','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l08','be sent out','',NULL,'/biː sent aʊt/','The dogs are sent out into the snow.','狗被派进雪地里。','Rescue teams were sent out at dawn.','救援队天一亮就被派了出去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l08','prefer A to B','',NULL,'/prɪˈfɜːr eɪ tuː biː/','The monks prefer winter to summer.','修道士们喜欢冬天胜过夏天。','I prefer tea to coffee.','比起咖啡,我更喜欢茶。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l08','be in trouble','',NULL,'/biː ɪn ˈtrʌbl/','The dogs go out whenever a hiker is in trouble.','只要徒步者遇险,狗就出动。','Call for help if you are in trouble.','遇到麻烦就呼救。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l08','be allowed to do','',NULL,'/biː əˈlaʊd tuː duː/','In winter the dogs are allowed to wander freely.','冬天狗获准自由走动。','Visitors are allowed to take photos here.','游客在这里获准拍照。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp1','choice','{"stem":"\"Each winter, the dogs ___ out into the snow to help lost hikers.\"(一般现在被动:are + 过去分词)","options":["are sent","sends","are sending","send"],"answer_index":0,"stem_cn":"每年冬天,这些狗都被派进雪中去帮迷路的徒步者。","explanation_cn":"“狗被派出去”是“被……”的意思,讲每年经常发生,用一般现在被动 are + 过去分词。✓ the dogs are sent out. ✗ send / sends:那是主动“派”;✗ are sending:进行时不合“经常如此”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp1','choice','{"stem":"\"In summer, the monastery ___ by thousands of tourists.\"(一般现在被动)","options":["is visiting","is visited","visits","visited"],"answer_index":1,"stem_cn":"夏天,修道院被成千上万的游客参观。","explanation_cn":"“修道院被游客参观”是“被……”,讲夏天经常如此,用一般现在被动 is + 过去分词。✓ it is visited by tourists. ✗ visits:主动;✗ visited:缺 be;✗ is visiting:意思变成“修道院在参观”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp1','choice','{"stem":"\"When crowds come, the dogs ___ inside an enclosure.\"(一般现在被动)","options":["are kept","keep","keeps","are keeping"],"answer_index":0,"stem_cn":"人群一来,狗就被关进围场里。","explanation_cn":"“狗被关在围场里”用一般现在被动 are + 过去分词。✓ the dogs are kept inside. ✗ keep / keeps:主动;✗ are keeping:意思不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp2','choice','{"stem":"\"The old monastery ___ almost two hundred years ago.\"(一般过去被动:was + 过去分词)","options":["founds","founded","was founding","was founded"],"answer_index":3,"stem_cn":"这座老修道院建于将近两百年前。","explanation_cn":"“修道院被建于两百年前”是过去的“被……”,用一般过去被动 was + 过去分词。✓ the monastery was founded. ✗ founded:少了 be,成了主动“建立了”;✗ founds / was founding:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp2','choice','{"stem":"\"Long ago, these dogs ___ mainly as watchdogs.\"(一般过去被动)","options":["used","use","were used","were using"],"answer_index":2,"stem_cn":"很久以前,这些狗主要被当作看门狗养。","explanation_cn":"“狗被当作看门狗养”是过去的“被……”,主语是复数,用 were + 过去分词。✓ the dogs were used as watchdogs. ✗ used:主动;✗ use / were using:时态或语态不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp2','choice','{"stem":"\"The first rescue dogs ___ here from far away.\"(一般过去被动:bring 的过去分词 brought)","options":["were bringing","were brought","brought","bring"],"answer_index":1,"stem_cn":"最早的救援犬是从很远的地方带到这里的。","explanation_cn":"“狗被带到这里”是过去被动,bring 的过去分词是 brought。✓ the dogs were brought here. ✗ brought:少了 be;✗ bring / were bringing:时态或语态不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp3','choice','{"stem":"\"A modern highway ___ through the mountains, so the pass is safer now.\"(现在完成被动:has been + 过去分词)","options":["built","builds","has been built","is building"],"answer_index":2,"stem_cn":"山中已修通一条现代公路,如今山口安全多了。","explanation_cn":"“公路已被修通”强调到现在为止的结果,用现在完成被动 has been + 过去分词。✓ a highway has been built. ✗ built:少了 has been;✗ builds / is building:时态或语态不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp3','choice','{"stem":"\"Over the years, many lives ___ by these brave dogs.\"(现在完成被动:have been + 过去分词)","options":["have been saved","save","are saving","saved"],"answer_index":0,"stem_cn":"多年来,这些勇敢的狗救过许多人的命。","explanation_cn":"“许多人命被救过”强调到现在的结果,主语是复数 lives,用 have been + 过去分词。✓ many lives have been saved. ✗ saved:少了 have been;✗ save / are saving:时态或语态不对。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp4','choice','{"stem":"\"Because of the crowds, the dogs have to ___ inside the enclosure.\"(情态词后的被动:be + 过去分词)","options":["being kept","kept","keep","be kept"],"answer_index":3,"stem_cn":"由于人多,狗不得不被关在围场里。","explanation_cn":"have to(不得不)后面接动词原形;要表达“被关”,就用 be + 过去分词。✓ the dogs have to be kept inside. ✗ keep / kept:配不出“被关”;✗ being kept:have to 后不接 being。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp4','choice','{"stem":"\"In winter the dogs ___ to wander wherever they like.\"(表示“被准许做某事”)","options":["allows","allow","are allowed","allowing"],"answer_index":2,"stem_cn":"冬天,狗获准想去哪儿就去哪儿。","explanation_cn":"“被准许做某事”用 be allowed to do。✓ the dogs are allowed to wander. ✗ allow / allows:主动;✗ allowing:缺 be。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp5','choice','{"stem":"\"The dogs are sent out ___ a hiker is in trouble.\"(“无论什么时候……都”,用哪个词)","options":["however","whatever","whoever","whenever"],"answer_index":3,"stem_cn":"只要有徒步者遇险,狗就被派出去。","explanation_cn":"“无论什么时候、一……就……”用 whenever。✓ whenever a hiker is in trouble. ✗ however 无论怎样;✗ whoever 无论谁;✗ whatever 无论什么——都不合。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp5','choice','{"stem":"\"In winter the dogs may go ___ they like.\"(“无论在哪里”,用哪个词)","options":["whoever","wherever","whenever","whatever"],"answer_index":1,"stem_cn":"冬天,狗想去哪儿就去哪儿。","explanation_cn":"“无论在哪里、想去哪儿就去哪儿”用 wherever。✓ go wherever they like. ✗ whenever 无论何时;✗ whoever 无论谁;✗ whatever 无论什么——都不合。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp5','choice','{"stem":"\"___ visits the monastery in winter gets a warm welcome.\"(“无论谁”,用哪个词)","options":["Whoever","Wherever","However","Whenever"],"answer_index":0,"stem_cn":"无论谁冬天来访,都会受到热情欢迎。","explanation_cn":"“无论谁……都”用 whoever。✓ Whoever visits gets a warm welcome. ✗ Whenever 无论何时;✗ Wherever 无论何地;✗ However 无论怎样——都不合。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp5','choice','{"stem":"\"The monks share ___ food they have with the skiers.\"(“无论什么、凡是”,用哪个词)","options":["however","wherever","whoever","whatever"],"answer_index":3,"stem_cn":"修道士们把自己有的食物都分给滑雪者。","explanation_cn":"“无论什么、凡是有的”用 whatever。✓ share whatever food they have. ✗ whoever 无论谁;✗ wherever 无论何地;✗ however 无论怎样——都不合。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp6','choice','{"stem":"\"A religious house where monks live and pray is a ___.\"(“修道院”用哪个词)","options":["factory","stadium","monastery","harbor"],"answer_index":2,"stem_cn":"僧侣居住、祈祷的宗教场所是修道院。","explanation_cn":"僧侣居住、祈祷的宗教场所叫 monastery(修道院)。✓ an old monastery. ✗ stadium 体育馆;✗ factory 工厂;✗ harbor 港口——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp6','choice','{"stem":"\"During the busy season the dogs are kept in a fenced ___.\"(“围场、圈地”用哪个词)","options":["ticket","mirror","ceiling","enclosure"],"answer_index":3,"stem_cn":"旺季时狗被关在带围栏的围场里。","explanation_cn":"带围栏、把动物圈起来的地方叫 enclosure(围场、圈地)。✓ a fenced enclosure. ✗ ceiling 天花板;✗ mirror 镜子;✗ ticket 门票——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp6','choice','{"stem":"\"People who slide down snowy slopes on long boards are ___.\"(“滑雪者”用哪个词)","options":["farmers","sailors","skiers","divers"],"answer_index":2,"stem_cn":"踩着长板从雪坡滑下的人是滑雪者。","explanation_cn":"踩着雪板从雪坡滑下的人叫 skiers(滑雪者)。✓ groups of skiers. ✗ sailors 水手;✗ divers 潜水员;✗ farmers 农民——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',5,'am3_l08_gp6','choice','{"stem":"\"In winter the quiet monks finally enjoy some ___.\"(“清静、隐私”用哪个词)","options":["noise","privacy","crowd","traffic"],"answer_index":1,"stem_cn":"冬天,清静的修道士终于享受到一些安宁。","explanation_cn":"“清静、不被打扰的私人空间”是 privacy。✓ enjoy some privacy. ✗ traffic 交通;✗ noise 噪音;✗ crowd 人群——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"monastery 的意思是:","options":["工厂","寺院,修道院","港口","体育馆"],"answer_index":1,"explanation_cn":"monastery = 寺院、修道院(僧侣居住修行的地方)。✓ a famous monastery 一座著名的修道院。\n顺带记:体育馆 = stadium;工厂 = factory;港口 = harbor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"monk 的意思是:","options":["和尚,僧侣","商人","医生","士兵"],"answer_index":0,"explanation_cn":"monk = 和尚、僧侣、修道士。✓ the monks prefer winter 修道士更爱冬天。\n顺带记:医生 = doctor;士兵 = soldier;商人 = merchant."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"enclosure 的意思是:","options":["天花板","门票","镜子","围场,圈地"],"answer_index":3,"explanation_cn":"enclosure = 围场、圈地(围起来养动物的地方)。✓ a special enclosure 专门的围场。\n顺带记:天花板 = ceiling;镜子 = mirror;门票 = ticket."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"privacy 的意思是:","options":["人群","清静,隐私","噪音","交通"],"answer_index":1,"explanation_cn":"privacy = 清静、不被打扰的隐私。✓ have some privacy 有些清静。\n顺带记:交通 = traffic;噪音 = noise;人群 = crowd."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"rashly 的意思是:","options":["缓慢地","小心地","高兴地","莽撞地,冒失地"],"answer_index":3,"explanation_cn":"rashly = 莽撞地、冒失地(不顾危险地)。✓ rashly try to cross the pass 冒失地翻越山口。\n顺带记:小心地 = carefully;缓慢地 = slowly;高兴地 = happily."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',6,NULL,'choice','{"stem":"\"whenever\" 的意思是:","options":["无论哪里","无论什么时候","无论谁","无论什么"],"answer_index":1,"explanation_cn":"whenever = 无论什么时候、每当。✓ whenever a hiker is in trouble 一有徒步者遇险。\n顺带记:无论谁 = whoever;无论哪里 = wherever;无论什么 = whatever."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',7,NULL,'cloze','{"stem":"第 1 空","context":"The old monastery ___1___ almost two hundred years ago. For centuries, brave dogs ___2___ out into the snow ___3___ a traveler is in trouble. Today a modern highway ___4___ through the pass, so it is much safer, but the dogs are still ready to help.","blank_no":1,"options":["founded","was founded","founds","is founding"],"answer_index":1,"explanation_cn":"“修道院被建于两百年前”是过去被动,用 was + 过去分词。✓ the monastery was founded."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',7,NULL,'cloze','{"stem":"第 2 空","context":"The old monastery ___1___ almost two hundred years ago. For centuries, brave dogs ___2___ out into the snow ___3___ a traveler is in trouble. Today a modern highway ___4___ through the pass, so it is much safer, but the dogs are still ready to help.","blank_no":2,"options":["are sent","send","sent","are sending"],"answer_index":0,"explanation_cn":"“狗被派进雪地”讲经常如此,用一般现在被动 are + 过去分词。✓ brave dogs are sent out."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',7,NULL,'cloze','{"stem":"第 3 空","context":"The old monastery ___1___ almost two hundred years ago. For centuries, brave dogs ___2___ out into the snow ___3___ a traveler is in trouble. Today a modern highway ___4___ through the pass, so it is much safer, but the dogs are still ready to help.","blank_no":3,"options":["whenever","however","whoever","whatever"],"answer_index":0,"explanation_cn":"“无论什么时候、一……就……”用 whenever。✓ whenever a traveler is in trouble."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',7,NULL,'cloze','{"stem":"第 4 空","context":"The old monastery ___1___ almost two hundred years ago. For centuries, brave dogs ___2___ out into the snow ___3___ a traveler is in trouble. Today a modern highway ___4___ through the pass, so it is much safer, but the dogs are still ready to help.","blank_no":4,"options":["builds","has been built","built","is building"],"answer_index":1,"explanation_cn":"“公路已被修通”强调到现在的结果,用现在完成被动 has been + 过去分词。✓ a highway has been built."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',8,NULL,'choice','{"stem":"What are the St. Bernard dogs used for?","options":["Rescuing travelers caught in the snow","Pulling heavy sleds of goods","Guarding the tourists'' cars","Herding mountain sheep"],"answer_index":0,"explanation_cn":"课文说 St. Bernard dogs have been kept there to rescue travelers caught in the snow——这些狗是用来营救被困雪中的旅人的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',8,NULL,'choice','{"stem":"Why do the monks prefer winter?","options":["The food is better","More tourists come","They finally have some privacy","The dogs sleep all day"],"answer_index":2,"explanation_cn":"课文说 The monks prefer winter to summer, because they finally have some privacy——冬天人少,修道士能清静些。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',8,NULL,'choice','{"stem":"Who visits the monastery in winter?","options":["Busloads of summer tourists","Groups of skiers at Christmas and Easter","Traveling salesmen","No one at all"],"answer_index":1,"explanation_cn":"课文说 The only regular guests in winter are groups of skiers who arrive at Christmas and Easter——冬天的常客是圣诞、复活节来的滑雪者。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',9,NULL,'choice','{"stem":"你想说\"这座修道院建于两百年前\"(一般过去被动 was founded):","options":["The monastery founded two hundred years ago by monks.","The monastery was founded two hundred years ago.","The monastery is founded two hundred years ago.","The monastery was find two hundred years ago."],"answer_index":1,"explanation_cn":"“被建立”用一般过去被动 was + 过去分词 founded(创建)。✓ The monastery was founded two hundred years ago. 场合:说某建筑“建于”某时。注意 was found 是“被发现”,意思不同。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',9,NULL,'choice','{"stem":"你想说\"无论谁冬天来都会受到热情欢迎\"(whoever):","options":["Whoever comes in winter gets a warm welcome.","Whoever come in winter gets a warm welcome.","Whatever comes in winter get a warm welcome.","However comes in winter gets a warm welcome."],"answer_index":0,"explanation_cn":"“无论谁来都……”用 whoever;它当第三人称单数,后面动词加 s(comes/gets)。✓ Whoever comes in winter gets a warm welcome. 场合:表示“不管谁,都……”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',9,NULL,'choice','{"stem":"你想说\"一有旅客遇险,狗就被派出去\"(whenever + 一般现在被动):","options":["Whenever a traveler is in trouble, the dogs send out.","Wherever a traveler is in trouble, the dogs are sent out.","Whenever a traveler is in trouble, the dogs are sent out.","Whenever a traveler is in trouble, the dogs are send out."],"answer_index":2,"explanation_cn":"“一有人遇险,狗就被派出去”:whenever 表“无论何时”,are sent out 是一般现在被动。✓ Whenever a traveler is in trouble, the dogs are sent out. 场合:一件事一发生,另一件事就随之发生。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"monastery 的意思是:","options":["寺院,修道院","港口","工厂","体育馆"],"answer_index":0,"explanation_cn":"monastery = 寺院、修道院。✓ a famous monastery."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"rashly 的意思是:","options":["缓慢地","小心地","莽撞地,冒失地","高兴地"],"answer_index":2,"explanation_cn":"rashly = 莽撞地、冒失地。✓ rashly try to cross the pass."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"\"In summer the monastery ___ by thousands of tourists.\"(一般现在被动)","options":["is visiting","visits","visited","is visited"],"answer_index":3,"stem_cn":"夏天修道院被成千上万的游客参观。","explanation_cn":"“修道院被游客参观”讲经常如此,用一般现在被动 is + 过去分词。✓ it is visited by tourists. ✗ visits / visited / is visiting:语态或时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"\"A new highway ___ through the mountains.\"(现在完成被动)","options":["is building","built","has been built","builds"],"answer_index":2,"stem_cn":"一条新公路已在山中修通。","explanation_cn":"“公路已被修通”强调到现在的结果,用现在完成被动 has been + 过去分词。✓ a new highway has been built. ✗ built / builds / is building:语态或时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"\"prefer winter to summer\" 的意思是:","options":["喜欢冬天胜过夏天","把冬天变成夏天","分不清冬夏","冬夏都不喜欢"],"answer_index":0,"explanation_cn":"prefer winter to summer = 喜欢冬天胜过夏天(prefer A to B)。✓ The monks prefer winter to summer."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"\"be in trouble\" 的意思是:","options":["准时到达","心情很好","陷入困境,遇到麻烦","休息一下"],"answer_index":2,"explanation_cn":"be in trouble = 陷入困境、遇到麻烦。✓ whenever a hiker is in trouble 只要徒步者遇险。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"Why are the dogs kept in an enclosure in summer?","options":["They are being punished","They dislike the heat","They are sick","There are too many tourists around"],"answer_index":3,"passage":"High in the Rocky Mountains, Eagle Pass connects two quiet valleys. At over eleven thousand feet, it is one of the highest passes in the country. An old stone monastery, which was founded almost two hundred years ago, stands about a mile from the top. For generations, big St. Bernard dogs have been kept there to rescue travelers caught in the snow. These gentle dogs, which were first raised as watchdogs, are still sent out into the storms whenever a hiker is in trouble. A modern highway has now been built through the mountains, so the pass is much safer. Even so, a few people still rashly try to cross it on foot, and the dogs are always ready. During the summer, the monastery is crowded, for it is visited by thousands of tourists who drive up to see it. Because so many people are around, the dogs have to be kept inside a special enclosure. In winter, however, everything changes. The temperature drops far below zero, and hardly anyone comes. The monks prefer winter to summer, because they finally have some privacy. The dogs are given more freedom, too, and are allowed to wander wherever they like. The only regular guests in winter are groups of skiers who arrive at Christmas and Easter. Whoever visits then is always given a warm welcome.","explanation_cn":"课文说 Because so many people are around, the dogs have to be kept inside a special enclosure——因为游客太多,才把狗关进围场。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"How has the new highway changed the pass?","options":["It has made the pass much safer","It has closed the monastery","It has scared away the dogs","It has stopped all skiers"],"answer_index":0,"passage":"High in the Rocky Mountains, Eagle Pass connects two quiet valleys. At over eleven thousand feet, it is one of the highest passes in the country. An old stone monastery, which was founded almost two hundred years ago, stands about a mile from the top. For generations, big St. Bernard dogs have been kept there to rescue travelers caught in the snow. These gentle dogs, which were first raised as watchdogs, are still sent out into the storms whenever a hiker is in trouble. A modern highway has now been built through the mountains, so the pass is much safer. Even so, a few people still rashly try to cross it on foot, and the dogs are always ready. During the summer, the monastery is crowded, for it is visited by thousands of tourists who drive up to see it. Because so many people are around, the dogs have to be kept inside a special enclosure. In winter, however, everything changes. The temperature drops far below zero, and hardly anyone comes. The monks prefer winter to summer, because they finally have some privacy. The dogs are given more freedom, too, and are allowed to wander wherever they like. The only regular guests in winter are groups of skiers who arrive at Christmas and Easter. Whoever visits then is always given a warm welcome.","explanation_cn":"课文说 A modern highway has now been built… so the pass is much safer——新公路让山口安全多了。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"When do the skiers visit?","options":["Every summer weekend","On rainy days","At Christmas and Easter","Never"],"answer_index":2,"audio":"High in the Rocky Mountains, Eagle Pass connects two quiet valleys. At over eleven thousand feet, it is one of the highest passes in the country. An old stone monastery, which was founded almost two hundred years ago, stands about a mile from the top. For generations, big St. Bernard dogs have been kept there to rescue travelers caught in the snow. These gentle dogs, which were first raised as watchdogs, are still sent out into the storms whenever a hiker is in trouble. A modern highway has now been built through the mountains, so the pass is much safer. Even so, a few people still rashly try to cross it on foot, and the dogs are always ready. During the summer, the monastery is crowded, for it is visited by thousands of tourists who drive up to see it. Because so many people are around, the dogs have to be kept inside a special enclosure. In winter, however, everything changes. The temperature drops far below zero, and hardly anyone comes. The monks prefer winter to summer, because they finally have some privacy. The dogs are given more freedom, too, and are allowed to wander wherever they like. The only regular guests in winter are groups of skiers who arrive at Christmas and Easter. Whoever visits then is always given a warm welcome.","explanation_cn":"课文说 groups of skiers who arrive at Christmas and Easter——滑雪者在圣诞和复活节来。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l08',10,NULL,'choice','{"stem":"What do the dogs get in winter?","options":["Less food","A new enclosure","Warm sweaters","More freedom to wander"],"answer_index":3,"audio":"High in the Rocky Mountains, Eagle Pass connects two quiet valleys. At over eleven thousand feet, it is one of the highest passes in the country. An old stone monastery, which was founded almost two hundred years ago, stands about a mile from the top. For generations, big St. Bernard dogs have been kept there to rescue travelers caught in the snow. These gentle dogs, which were first raised as watchdogs, are still sent out into the storms whenever a hiker is in trouble. A modern highway has now been built through the mountains, so the pass is much safer. Even so, a few people still rashly try to cross it on foot, and the dogs are always ready. During the summer, the monastery is crowded, for it is visited by thousands of tourists who drive up to see it. Because so many people are around, the dogs have to be kept inside a special enclosure. In winter, however, everything changes. The temperature drops far below zero, and hardly anyone comes. The monks prefer winter to summer, because they finally have some privacy. The dogs are given more freedom, too, and are allowed to wander wherever they like. The only regular guests in winter are groups of skiers who arrive at Christmas and Easter. Whoever visits then is always given a warm welcome.","explanation_cn":"课文说 The dogs are given more freedom, too, and are allowed to wander——冬天狗获得更多自由,可以四处走动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
